import{_ as a,o as t,c as r,ae as n}from"./chunks/framework.Dn6zxbF8.js";const d=JSON.parse('{"title":"Notion: hierarchy, audiences, and access","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1917971986/references/notion.md","filePath":"adrs/1917971986/references/notion.md"}'),s={name:"adrs/1917971986/references/notion.md"};function o(i,e,l,h,c,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="notion-hierarchy-audiences-and-access" tabindex="-1">Notion: hierarchy, audiences, and access <a class="header-anchor" href="#notion-hierarchy-audiences-and-access" aria-label="Permalink to &quot;Notion: hierarchy, audiences, and access&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-10.</p><h2 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h2><p>A Notion workspace is the top-level container a person works inside. Within a workspace, members organize work in teamspaces, described as an organizational layer that creates a dedicated area for a team while staying connected to the wider workspace (<a href="https://www.notion.com/help/guides/teamspaces-give-teams-home-for-important-work" target="_blank" rel="noreferrer">Teamspaces give every team a home for important work</a>). Every workspace has at least one default teamspace, called General, that includes every member, and owners can add further teamspaces for departments, cross-functional groups, or projects (<a href="https://www.notion.com/help/guides/teamspaces-give-teams-home-for-important-work" target="_blank" rel="noreferrer">Teamspaces give every team a home for important work</a>; <a href="https://www.notion.com/help/intro-to-teamspaces" target="_blank" rel="noreferrer">Intro to teamspaces</a>). Inside a teamspace, members add top-level pages, which can then hold any number of subpages nested below them; Notion&#39;s own documentation does not describe teamspaces as able to contain other teamspaces, only pages and their subpages (<a href="https://www.notion.com/help/guides/teamspaces-give-teams-home-for-important-work" target="_blank" rel="noreferrer">Teamspaces give every team a home for important work</a>). Pages nest without a documented depth limit, and a subpage can itself hold further subpages (<a href="https://www.notion.com/help/sharing-and-permissions" target="_blank" rel="noreferrer">Sharing and permissions</a>).</p><p>On Enterprise plans, verifying an email domain creates a governance surface, described in Notion&#39;s documentation as letting an organization&#39;s owners see and, under conditions, claim other workspaces created by people using addresses on that domain (<a href="https://www.notion.com/help/domain-management" target="_blank" rel="noreferrer">Domain management</a>). This is not the same as a workspace containing other workspaces: a claimed workspace keeps operating as its own separate workspace, with its own data and membership, unless it is later consolidated (<a href="https://www.notion.com/help/domain-management" target="_blank" rel="noreferrer">Domain management</a>).</p><h2 id="governance-and-work" tabindex="-1">Governance and work <a class="header-anchor" href="#governance-and-work" aria-label="Permalink to &quot;Governance and work&quot;">​</a></h2><p>Membership, roles, and admin rights (owner, membership admin, member, guest) are configured per workspace (<a href="https://www.notion.com/help/add-members-admins-guests-and-groups" target="_blank" rel="noreferrer">Manage members &amp; guests</a>). On Enterprise, domain verification extends part of that governance across every workspace sharing the verified domain: it unlocks SAML SSO configuration and lets an organization control who on that domain may create new workspaces at all (<a href="https://www.notion.com/help/domain-management" target="_blank" rel="noreferrer">Domain management</a>). Security policy that caps sharing, export, and moving pages between workspaces is also set at the workspace level, in Settings, Security (<a href="https://www.notion.com/help/workspace-settings" target="_blank" rel="noreferrer">Workspace settings</a>).</p><p>Billing is per workspace. An Enterprise organization that claims another workspace created on its verified domain can offer to upgrade it, but each workspace remains its own billable unit until it is formally consolidated (<a href="https://www.notion.com/help/domain-management" target="_blank" rel="noreferrer">Domain management</a>). Work itself, the pages and their content, lives inside teamspaces and the page tree beneath them, separate from the workspace-level identity and billing settings (<a href="https://www.notion.com/help/guides/teamspaces-give-teams-home-for-important-work" target="_blank" rel="noreferrer">Teamspaces give every team a home for important work</a>).</p><h2 id="audiences-and-visibility" tabindex="-1">Audiences and visibility <a class="header-anchor" href="#audiences-and-visibility" aria-label="Permalink to &quot;Audiences and visibility&quot;">​</a></h2><p>When sharing a page, Notion exposes several audiences: specific people, who may be workspace members or outside guests; a teamspace; the whole workspace; or anyone on the web with a link (<a href="https://www.notion.com/help/sharing-and-permissions" target="_blank" rel="noreferrer">Sharing and permissions</a>). Teamspaces themselves come in three types that set a default audience for what is created inside them. Open teamspaces let anyone in the workspace join and view all content inside. Closed teamspaces are visible to everyone in the workspace, but joining requires an invitation from an owner or member. Private teamspaces, available only on Business and Enterprise plans, are not visible at all to people who are not members, and only members or owners can invite others in (<a href="https://www.notion.com/help/intro-to-teamspaces" target="_blank" rel="noreferrer">Intro to teamspaces</a>).</p><p>A new subpage takes on the sharing of its parent page by default (<a href="https://www.notion.com/help/sharing-and-permissions" target="_blank" rel="noreferrer">Sharing and permissions</a>). Where a person has more than one grant that applies to the same page, Notion gives them the broadest one: someone with view-only access directly on a page who also has full access through workspace membership keeps full access (<a href="https://www.notion.com/help/sharing-and-permissions" target="_blank" rel="noreferrer">Sharing and permissions</a>).</p><h2 id="narrowing-below-a-parent" tabindex="-1">Narrowing below a parent <a class="header-anchor" href="#narrowing-below-a-parent" aria-label="Permalink to &quot;Narrowing below a parent&quot;">​</a></h2><p>A subpage can be restricted below what its parent grants. A subpage takes on its parent&#39;s permissions, and &quot;to change this, go into a subpage and update the permissions there&quot; (<a href="https://www.notion.com/help/sharing-and-permissions" target="_blank" rel="noreferrer">Sharing and permissions</a>). Notion&#39;s release notes state the restricting direction explicitly: before the change, nested pages &quot;always inherited the permission level of the parent page&quot;, and since then &quot;you can expand or restrict permissions for any sub-page&quot; (<a href="https://www.notion.com/releases/2020-11-11" target="_blank" rel="noreferrer">Release notes, November 11, 2020</a>). Notion also &quot;respects the broadest level of access given to a user&quot;, so a restriction on a subpage does not hold against broader access reaching the person by another route (<a href="https://www.notion.com/help/sharing-and-permissions" target="_blank" rel="noreferrer">Sharing and permissions</a>). One boundary on narrowing: moving a shared page into a member&#39;s private sidebar section removes other people&#39;s access to that page, but any subpages beneath it keep whatever access they already had, so a narrowing action on a parent does not automatically cascade down to its children (<a href="https://www.notion.com/help/sharing-and-permissions" target="_blank" rel="noreferrer">Sharing and permissions</a>).</p><h2 id="ceilings-from-above" tabindex="-1">Ceilings from above <a class="header-anchor" href="#ceilings-from-above" aria-label="Permalink to &quot;Ceilings from above&quot;">​</a></h2><p>Enterprise workspace owners can set security policy, in Settings, Security, that caps what every member may do workspace-wide: preventing members from publishing pages or forms publicly on the web, disabling guest invitations, disabling moving or duplicating pages to other workspaces, and disabling export of page and database content (<a href="https://www.notion.com/help/workspace-settings" target="_blank" rel="noreferrer">Workspace settings</a>; <a href="https://www.notion.com/help/guides/understanding-notions-sharing-settings" target="_blank" rel="noreferrer">Understanding Notion&#39;s sharing settings</a>). These controls are opt-in: an Enterprise workspace owner chooses to turn them on, and a workspace that enables none of them leaves members free to share, export, and move pages as they choose (<a href="https://www.notion.com/help/guides/understanding-notions-sharing-settings" target="_blank" rel="noreferrer">Understanding Notion&#39;s sharing settings</a>). A teamspace&#39;s own security settings automatically inherit from the workspace&#39;s security settings, and only a teamspace owner who is also a workspace owner can change them, which keeps a workspace-level ceiling in force at the teamspace layer (<a href="https://www.notion.com/help/intro-to-teamspaces" target="_blank" rel="noreferrer">Intro to teamspaces</a>).</p><p>Below Enterprise, plan tier itself acts as a softer ceiling. Allowing outsiders to request access to a page is on by default for Free, Plus, and Business plans, and can be turned off only on Plus and Business; Enterprise instead ships with this off and lets an owner turn it on (<a href="https://www.notion.com/help/add-members-admins-guests-and-groups" target="_blank" rel="noreferrer">Manage members &amp; guests</a>; <a href="https://www.notion.com/help/workspace-settings" target="_blank" rel="noreferrer">Workspace settings</a>). Private teamspaces are gated the same way: they exist only on Business and Enterprise plans, so a Free or Plus workspace has no way to create one (<a href="https://www.notion.com/help/intro-to-teamspaces" target="_blank" rel="noreferrer">Intro to teamspaces</a>).</p><h2 id="discovery-versus-access" tabindex="-1">Discovery versus access <a class="header-anchor" href="#discovery-versus-access" aria-label="Permalink to &quot;Discovery versus access&quot;">​</a></h2><p>A closed teamspace stays discoverable: everyone in the workspace can see that it exists, but cannot open its content without being invited by an owner or member. A private teamspace removes discovery as well as access, since it is not visible at all to people who are not members (<a href="https://www.notion.com/help/intro-to-teamspaces" target="_blank" rel="noreferrer">Intro to teamspaces</a>).</p><p>For pages, a person outside a workspace who reaches a page link can request access, and the page&#39;s owner or an admin approves or denies the request; this is on by default for Free, Plus, and Business plans, and can be disabled on Plus and Business, while Enterprise has it available but off by default until an owner enables it (<a href="https://www.notion.com/help/add-members-admins-guests-and-groups" target="_blank" rel="noreferrer">Manage members &amp; guests</a>; <a href="https://www.notion.com/help/workspace-settings" target="_blank" rel="noreferrer">Workspace settings</a>). Someone who already has view or comment access to a page can also request a higher level, such as edit access, and that request goes to the page&#39;s owner for a decision (<a href="https://www.notion.com/help/sharing-and-permissions" target="_blank" rel="noreferrer">Sharing and permissions</a>).</p><h2 id="small-customers" tabindex="-1">Small customers <a class="header-anchor" href="#small-customers" aria-label="Permalink to &quot;Small customers&quot;">​</a></h2><p>Signing up for Notion simply creates a workspace; there is no separate organization object to configure first, and identity, billing, and membership all live on that workspace from the start (<a href="https://www.notion.com/help/add-members-admins-guests-and-groups" target="_blank" rel="noreferrer">Manage members &amp; guests</a>). The Enterprise-only governance surface, domain verification, claimable workspaces, and cross-workspace security policy, only becomes relevant once a company moves to an Enterprise plan and verifies a domain (<a href="https://www.notion.com/help/domain-management" target="_blank" rel="noreferrer">Domain management</a>). A workspace with a single member that has no outstanding paid-plan balance can be deleted outright, so a solo user never has to interact with that governance surface at all (<a href="https://www.notion.com/help/domain-management" target="_blank" rel="noreferrer">Domain management</a>).</p><h2 id="consolidation" tabindex="-1">Consolidation <a class="header-anchor" href="#consolidation" aria-label="Permalink to &quot;Consolidation&quot;">​</a></h2><p>Notion does not merge separately created workspaces as an ordinary admin action. Enterprise domain verification lets an organization&#39;s owners claim other workspaces created with its verified domain, request ownership transfer of single-member workspaces, or offer an upgrade to multi-member workspaces, but each claimed workspace keeps operating on its own until it is actually merged (<a href="https://www.notion.com/help/domain-management" target="_blank" rel="noreferrer">Domain management</a>). Merging workspaces together is handled as workspace consolidation, which Notion describes as available to sales-assisted Enterprise customers through their Notion account management team, not as a self-service tool in workspace settings (<a href="https://www.notion.com/help/domain-management" target="_blank" rel="noreferrer">Domain management</a>).</p><h2 id="relevance-to-this-adr" tabindex="-1">Relevance to this ADR <a class="header-anchor" href="#relevance-to-this-adr" aria-label="Permalink to &quot;Relevance to this ADR&quot;">​</a></h2><ul><li>Notion&#39;s workspace plays this ADR&#39;s Workspace role for everyday work, but Notion has no always-present Organization node the way this ADR&#39;s tenant root always exists in the data. Notion&#39;s Enterprise organization layer appears only for customers who verify a domain, and it governs a set of separately billed workspaces rather than a single tenant tree (<a href="https://www.notion.com/help/domain-management" target="_blank" rel="noreferrer">Domain management</a>). This diverges from the ADR&#39;s position that the organization is never optional in the data, only in the interface.</li><li>Notion&#39;s teamspace maps closer to this ADR&#39;s Folder than to its Workspace: a teamspace sits inside a workspace, groups pages, and sets a default audience for what is created inside it (<a href="https://www.notion.com/help/intro-to-teamspaces" target="_blank" rel="noreferrer">Intro to teamspaces</a>), the same role this ADR assigns to folders narrowing or widening what descendants start with.</li><li>Notion&#39;s subpage restriction agrees with this ADR&#39;s rule that any level may narrow below its parent: a subpage&#39;s own Share settings can reduce access below what it inherited, and Notion marks the page as no longer fully inheriting (<a href="https://www.notion.com/help/sharing-and-permissions" target="_blank" rel="noreferrer">Sharing and permissions</a>), the same shape as this ADR&#39;s per-level limit.</li><li>Notion&#39;s closed-versus-private teamspace split is a concrete example of this ADR&#39;s discovery-versus-access distinction: closed teamspaces stay discoverable while access is still gated, and private teamspaces hide existence entirely (<a href="https://www.notion.com/help/intro-to-teamspaces" target="_blank" rel="noreferrer">Intro to teamspaces</a>), matching this ADR&#39;s statement that a limit can leave discovery open or close it.</li><li>Notion&#39;s lack of a self-service merge for separately created workspaces, since consolidation runs through Notion&#39;s account management team rather than an ordinary setting (<a href="https://www.notion.com/help/domain-management" target="_blank" rel="noreferrer">Domain management</a>), lines up with this ADR&#39;s position that separately created organizations consolidate only through an explicit migration, never an ordinary tree operation.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://www.notion.com/help/guides/teamspaces-give-teams-home-for-important-work" target="_blank" rel="noreferrer">Teamspaces give every team a home for important work</a></li><li><a href="https://www.notion.com/help/intro-to-teamspaces" target="_blank" rel="noreferrer">Intro to teamspaces</a></li><li><a href="https://www.notion.com/help/domain-management" target="_blank" rel="noreferrer">Domain management</a></li><li><a href="https://www.notion.com/help/sharing-and-permissions" target="_blank" rel="noreferrer">Sharing and permissions</a></li><li><a href="https://www.notion.com/releases/2020-11-11" target="_blank" rel="noreferrer">Release notes, November 11, 2020</a></li><li><a href="https://www.notion.com/help/add-members-admins-guests-and-groups" target="_blank" rel="noreferrer">Manage members &amp; guests</a></li><li><a href="https://www.notion.com/help/guides/understanding-notions-sharing-settings" target="_blank" rel="noreferrer">Understanding Notion&#39;s sharing settings</a></li><li><a href="https://www.notion.com/help/workspace-settings" target="_blank" rel="noreferrer">Workspace settings</a></li></ul>',27)])])}const g=a(s,[["render",o]]);export{d as __pageData,g as default};
